      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-openai-oauth\",\n  \"version\": \"0.3.0\",\n  \"description\": \"Self-contained OpenAI Codex OAuth provider for DeepSeek Harness\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/AdonisSheldon/dsh-openai-oauth.git\"\n  },\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/client.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"bin\": {\n    \"dsh-openai-login\": \"lib/login.js\"\n  },\n  \"files\": [\n    \"lib/client.d.ts\",\n    \"lib/client.js\",\n    \"lib/index.d.ts\",\n    \"lib/index.js\",\n    \"lib/login.d.ts\",\n    \"lib/login.js\",\n    \"lib/src.js\",\n    \"cordis.patch.yml\",\n    \"docs/assets/readme-header.svg\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"SECURITY.md\",\n    \"LICENSE\",\n    \"THIRD_PARTY_NOTICES.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsdown\",\n    \"check\": \"pnpm run typecheck && pnpm run build\",\n    \"typecheck\": \"tsc --noEmit\"\n  },\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"openai\",\n    \"codex\",\n    \"oauth\"\n  ],\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \"0.2.1-rc.5\"\n  },\n  \"dependencies\": {\n    \"proper-lockfile\": \"4.1.2\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-attachment\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-home-paths\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-timeout\": \"0.2.1-rc.5\",\n    \"react\": \"^18.3.1\",\n    \"@deepseek-ai/dsh-web\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-attachment\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-renderer\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-home-paths\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-host-webserver\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-timeout\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-web\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-agent\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/dsh-attachment\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-home-paths\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-timeout\": \"0.2.1-rc.5\",\n    \"@types/node\": \"22.20.0\",\n    \"@types/proper-lockfile\": \"4.1.4\",\n    \"@types/react\": \"18.3.28\",\n    \"react\": \"18.3.1\",\n    \"tsdown\": \"0.22.2\",\n    \"typescript\": \"5.9.2\",\n    \"@deepseek-ai/dsh-web\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\"\n  },\n  \"packageManager\": \"pnpm@11.1.3\"\n}\n"
